for (const n of [10, 20, 40]) {
  const quad = n * n;
  const exp = 2 ** n;
  console.log(`n=${n}  n^2=${quad.toLocaleString()}  2^n=${exp.toLocaleString()}`);
}
console.log('---');
console.log('At n=10: n^2 is 100, 2^n is ~1 thousand.');
console.log('At n=20: n^2 is 400, 2^n is ~1 million.');
console.log('At n=40: n^2 is 1,600, 2^n is ~1 trillion. Quadratic crawls; exponential explodes.');

